import * as THREE from 'three/webgpu';
import { color, uniform, vertexColor, mix, uv, positionLocal, float } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'testimonial-panel';
  const { x = 0, y = 0, z = 0 } = config.scenePosition?.position || {};
  const rot = config.scenePosition?.rotation || { x: 0, y: 0, z: 0 };
  const scl = config.scenePosition?.scale || { x: 1, y: 1, z: 1 };
  group.position.set(x, y, z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const PANEL_W = 3.4;
  const PANEL_H = 1.9;

  const disposables = [];
  const timelines = [];

  // --- Panel with engineered gradient + hairline border ---
  const panelGeo = new THREE.PlaneGeometry(PANEL_W, PANEL_H, 1, 1);
  disposables.push(panelGeo);

  const topColor = color('#1a1a22');
  const botColor = color('#111116');
  const gradFactor = uv().y;
  const panelMat = new THREE.MeshStandardNodeMaterial();
  panelMat.colorNode = mix(botColor, topColor, gradFactor);
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.2;
  panelMat.clearcoat = 0.1;
  disposables.push(panelMat);

  const panelMesh = new THREE.Mesh(panelGeo, panelMat);
  panelMesh.position.z = 0;
  group.add(panelMesh);

  // hairline border via slightly larger plane behind
  const borderGeo = new THREE.PlaneGeometry(PANEL_W + 0.012, PANEL_H + 0.012, 1, 1);
  disposables.push(borderGeo);
  const borderMat = new THREE.MeshStandardNodeMaterial();
  borderMat.colorNode = color('#26262f');
  borderMat.roughness = 0.6;
  borderMat.metalness = 0.2;
  disposables.push(borderMat);
  const borderMesh = new THREE.Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.001;
  group.add(borderMesh);

  // helper to convert top-left padded coords to plane-local coords
  const left = -PANEL_W / 2;
  const top = PANEL_H / 2;
  const pad = 0.5;

  // --- Quotation mark, extruded ---
  const quoteMarkMesh = createTextMesh({
    text: config.textContent?.[0]?.text ?? '"',
    fontAtlas: ctx.fontAtlas,
    family: 'Lora',
    fontWeight: 600,
    fontSize: 62,
    lineHeight: 1,
    letterSpacing: 0,
    color: '#ff2a38',
    maxWidth: null,
    extrude: 0.04,
    roughness: 0.5,
    metalness: 0.3
  });
  quoteMarkMesh.position.set(left + pad, top - pad - 0.4, 0.02);
  group.add(quoteMarkMesh);
  disposables.push(quoteMarkMesh.geometry, quoteMarkMesh.material);

  // --- Quote text ---
  const quoteMesh = createTextMesh({
    text: config.textContent?.[1]?.text ?? '',
    fontAtlas: ctx.fontAtlas,
    family: 'Lora',
    fontWeight: 400,
    fontSize: 20,
    lineHeight: 1.45,
    letterSpacing: 0,
    color: '#e8ecf2',
    maxWidth: 2.4
  });
  quoteMesh.position.set(left + pad, top - pad - 0.4 - 0.25 - 0.62 * 0.35, 0.03);
  group.add(quoteMesh);
  disposables.push(quoteMesh.geometry, quoteMesh.material);

  // --- Attribution rule ---
  const ruleGeo = new THREE.PlaneGeometry(0.2, 0.02, 1, 1);
  disposables.push(ruleGeo);
  const ruleMat = new THREE.MeshStandardNodeMaterial();
  ruleMat.colorNode = color('#ff2a38');
  ruleMat.emissiveNode = color('#ff2a38').mul(float(1.4));
  ruleMat.roughness = 0.5;
  ruleMat.metalness = 0.2;
  disposables.push(ruleMat);
  const ruleMesh = new THREE.Mesh(ruleGeo, ruleMat);
  const attribY = quoteMesh.position.y - 0.4 - 0.25;
  ruleMesh.position.set(left + pad + 0.1, attribY, 0.02);
  group.add(ruleMesh);

  // --- Attribution text ---
  const attribMesh = createTextMesh({
    text: config.textContent?.[2]?.text ?? '',
    fontAtlas: ctx.fontAtlas,
    family: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 13,
    lineHeight: 1.2,
    letterSpacing: 0.08,
    color: '#e8ecf2',
    maxWidth: null
  });
  attribMesh.position.set(left + pad + 0.28, attribY - 0.005, 0.02);
  group.add(attribMesh);
  disposables.push(attribMesh.geometry, attribMesh.material);

  // --- Caption text ---
  const captionMesh = createTextMesh({
    text: config.textContent?.[3]?.text ?? '',
    fontAtlas: ctx.fontAtlas,
    family: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 9,
    lineHeight: 1.4,
    letterSpacing: 0.12,
    color: '#8a8a94',
    maxWidth: null
  });
  captionMesh.position.set(left + pad + 0.28, attribY - 0.18, 0.02);
  group.add(captionMesh);
  disposables.push(captionMesh.geometry, captionMesh.material);

  // --- Mount animation ---
  group.visible = true;
  group.position.y += 0.2;
  panelMat.opacity = 0;
  panelMat.transparent = true;
  borderMat.opacity = 0;
  borderMat.transparent = true;

  const opacityTarget = { v: 0 };
  const tl = gsap.timeline();
  timelines.push(tl);

  tl.to(group.position, {
    y: group.position.y - 0.2,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
  }, 0);
  tl.to(opacityTarget, {
    v: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    onUpdate: () => {
      panelMat.opacity = opacityTarget.v;
      borderMat.opacity = opacityTarget.v;
    }
  }, 0);

  quoteMarkMesh.scale.set(1.04, 1.04, 1.04);
  tl.to(quoteMarkMesh.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)'
  }, 0.5);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    disposables.forEach(d => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose?.();
      if (obj.material) {
        if (Array.isArray(obj.material)) obj.material.forEach(m => m.dispose?.());
        else obj.material.dispose?.();
      }
    });
  };

  return group;
}
